def source_snapshot():
    """Return verified exact bytes. Shared admission and native checks remain pending."""
    if len(MANIFEST) != len(_ENCODED):
        raise ValueError("Incomplete current-source baseline")
    result = {}
    for row, encoded in zip(MANIFEST, _ENCODED):
        raw = zlib.decompress(base64.b85decode(encoded))
        if len(raw) != row["bytes"] or hashlib.sha256(raw).hexdigest() != row["sha256"]:
            raise ValueError("Current-source snapshot changed: " + row["relative"])
        result[row["relative"]] = raw
    return result
